                >
                  {issue.text}
                </li>
              ))}
            </ul>
          )}
        </section>
      )}
    </div>
  );
}

function KpiTile(props: {
  label: string;
  primary: string;
  secondary?: string;
  tone: 'ok' | 'warn' | 'alert';
